def handle_partial_and_final_results(responses):
    for response in responses:
        if not response.results:
            continue

        result = response.results[0]
        if not result.alternatives:
            continue

        transcript = result.alternatives[0].transcript

        if result.is_final:
            print(f"Final: {transcript}")
        else:
            print(f"Partial: {transcript}")

from google.cloud import speech_v1p1beta1 as speech


def get_speech_client():
    return speech.SpeechClient()


def create_recognition_config(
    sample_rate_hertz: int,
    language_code: str,
    model: str = "video",
    enable_automatic_punctuation: bool = True,
):
    return speech.RecognitionConfig(
        encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
        sample_rate_hertz=sample_rate_hertz,
        language_code=language_code,
        model=model,
        enable_automatic_punctuation=enable_automatic_punctuation,
    )


def create_streaming_config(recognition_config, interim_results: bool = True):
    return speech.StreamingRecognitionConfig(
        config=recognition_config,
        interim_results=interim_results,
    )

from dataclasses import dataclass


@dataclass
class StreamingRecognitionRequest:
    audio_content: bytes


@dataclass
class StreamingRecognitionResponse:
    transcript: str
    is_final: bool


def normalize_google_response(response):
    if not response.results:
        return None

    result = response.results[0]
    if not result.alternatives:
        return None

    return StreamingRecognitionResponse(
        transcript=result.alternatives[0].transcript,
        is_final=result.is_final,
    )

from google.cloud import translate_v3 as translate


def translate_caption(text: str, target_language: str = "es") -> str:
    client = translate.TranslationServiceClient()
    project_id = "your-gcp-project-id"  # Replace with your GCP Project ID
    location = "global"

    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language,
        }
    )

    for translation in response.translations:
        return translation.translated_text
    return ""
